    private String guid;
    private String sitename;        // 站名
    private BigDecimal longitude;   // 经度
    private BigDecimal latitude;     // 纬度
    private String type;             // TYPE 字段 (Mobile/Broadcasting/Fixed/Satellite/Microwave/Navigation)
